mapper.select:
select a.*
from margin_base_info a,contract_base_info b

    a.contract_id = b.id
    and a.client_id = #{dto.clientId}
    and a.contract_code LIKE concat('%', #{dto.contractCode},'%')
    and a.collection_amount  >=  #{dto.amountFrom}
    and a.collection_amount  <=  #{dto.amountTo}
    and a.collection_date  >=  #{dto.collectionDateFrom}
    and a.collection_date  <=  #{dto.collectionDateTo}


order by a.create_time desc
